/*
 * t_v12.c -- host tests for the V12 A32 class functions n2a32_arm_mem / n2a32_arm_misc.
 *
 * Unit tests call the class functions directly on a struct n2a32_cpu whose mem->base is a
 * 16 MiB calloc (guest addresses below 16 MiB), exactly as required by the package task.
 * All instruction words come from ALL_ENC[], generated by run_tests.sh from assembly text
 * through llvm-mc.  The expected register, flag and memory values below are literals worked
 * out from the ARM ARM pseudocode, not from the implementation.
 *
 * The random sweep uses a separate 4 GiB PROT_READ|WRITE MAP_NORESERVE reservation so that
 * every 32-bit address a random encoding can form is backed; it is touched only near 0 and
 * near 4 GiB because the sweep keeps every general register at zero.  This lets the sweep
 * prove "OK or UNDEF, never a crash" for arbitrary words without a signal handler.
 */
#define _DEFAULT_SOURCE 1
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <sys/mman.h>

#include "n2a32.h"
#include "enc.h"

#define GUEST_SIZE (16u << 20)

static uint8_t *g_base;
static struct n2a32_mem M;
static struct n2a32_cpu C;
static unsigned checks, failures;
static const char *tname;

/* ------------------------------------------------------------------ test doubles */

static unsigned mmio_reads, mmio_writes, mmio_bytes;
static uint32_t mmio_addr, mmio_val, mmio_ret;

static uint32_t test_mmio_rd(void *ctx, uint32_t a, unsigned bytes)
{
	(void)ctx;
	mmio_reads++;
	mmio_addr = a;
	mmio_bytes = bytes;
	return mmio_ret;
}

static void test_mmio_wr(void *ctx, uint32_t a, unsigned bytes, uint32_t v)
{
	(void)ctx;
	mmio_writes++;
	mmio_addr = a;
	mmio_bytes = bytes;
	mmio_val = v;
}

/* The core (V02) provides these two in the real build. */
uint32_t n2a32_mmio_load(struct n2a32_mem *m, uint32_t a, unsigned bytes)
{
	unsigned idx = m->mmio_idx[a >> N2A32_MMIO_SHIFT];
	return m->mmio[idx].rd(m->mmio[idx].ctx, a, bytes);
}

void n2a32_mmio_store(struct n2a32_mem *m, uint32_t a, unsigned bytes, uint32_t v)
{
	unsigned idx = m->mmio_idx[a >> N2A32_MMIO_SHIFT];
	m->mmio[idx].wr(m->mmio[idx].ctx, a, bytes, v);
}

/* Stand-in for V02's n2a32_excl.c: value-based compare-and-swap, 1/2/4/8 bytes. */
static unsigned excl_bytes;
static uint64_t excl_value;

void n2a32_excl_mark(struct n2a32_cpu *c, uint32_t addr, unsigned bytes, uint64_t value)
{
	c->excl_addr = addr;
	c->excl_valid = 1;
	excl_bytes = bytes;
	excl_value = value;
}

int n2a32_excl_store(struct n2a32_cpu *c, uint32_t addr, unsigned bytes, uint64_t value)
{
	uint64_t cur;

	if (!c->excl_valid || c->excl_addr != addr) {
		c->excl_valid = 0;
		return 1;
	}
	switch (bytes) {
	case 1: cur = n2a32_ld8(c, addr); break;
	case 2: cur = n2a32_ld16(c, addr); break;
	case 4: cur = n2a32_ld32(c, addr); break;
	default: cur = n2a32_ld64(c, addr); break;
	}
	if (cur != excl_value) {
		c->excl_valid = 0;
		return 1;
	}
	switch (bytes) {
	case 1: n2a32_st8(c, addr, (uint8_t)value); break;
	case 2: n2a32_st16(c, addr, (uint16_t)value); break;
	case 4: n2a32_st32(c, addr, (uint32_t)value); break;
	default: n2a32_st64(c, addr, value); break;
	}
	c->excl_valid = 0;
	return 0;
}

/* Raw guest memory helpers for test setup and inspection (no MMIO hook). */
static uint32_t raw_ld32(uint32_t a) { uint32_t v; memcpy(&v, g_base + a, 4); return v; }
static uint16_t raw_ld16(uint32_t a) { uint16_t v; memcpy(&v, g_base + a, 2); return v; }
static uint8_t  raw_ld8(uint32_t a)  { uint8_t v;  memcpy(&v, g_base + a, 1); return v; }
static void raw_st32(uint32_t a, uint32_t v) { memcpy(g_base + a, &v, 4); }
static void raw_st16(uint32_t a, uint16_t v) { memcpy(g_base + a, &v, 2); }
static void raw_st8(uint32_t a, uint8_t v)   { memcpy(g_base + a, &v, 1); }

/* ------------------------------------------------------------------ harness */

#define CHECK(x) do { checks++; if (!(x)) { failures++; \
	fprintf(stderr, "FAIL [%s] %s:%d: %s\n", tname, __FILE__, __LINE__, #x); } } while (0)
#define CHECK_EQ(a, b) do { uint32_t a_ = (uint32_t)(a), b_ = (uint32_t)(b); checks++; \
	if (a_ != b_) { failures++; fprintf(stderr, "FAIL [%s] %s:%d: %s = 0x%08x, expected 0x%08x (%s)\n", \
	tname, __FILE__, __LINE__, #a, a_, b_, #b); } } while (0)
#define CHECK64(a, b) do { uint64_t a_ = (uint64_t)(a), b_ = (uint64_t)(b); checks++; \
	if (a_ != b_) { failures++; fprintf(stderr, "FAIL [%s] %s:%d: %s = 0x%016llx, expected 0x%016llx (%s)\n", \
	tname, __FILE__, __LINE__, #a, (unsigned long long)a_, (unsigned long long)b_, #b); } } while (0)

#define MEM_OK(e)    CHECK_EQ(n2a32_arm_mem(&C, (e)), N2A32_OK)
#define MEM_UNDEF(e) CHECK_EQ(n2a32_arm_mem(&C, (e)), N2A32_UNDEF)
#define MISC_OK(e)   CHECK_EQ(n2a32_arm_misc(&C, (e)), N2A32_OK)
#define MISC_UNDEF(e) CHECK_EQ(n2a32_arm_misc(&C, (e)), N2A32_UNDEF)

static void reset(void)
{
	memset(&C, 0, sizeof C);
	memset(g_base, 0, 0x3000);
	memset(g_base + 0x00F00000u, 0, 0x100);
	C.mem = &M;
	C.r[13] = 0x00F00000u;
	C.next_pc = 0x1004;
	C.r[15] = 0x1008;              /* instruction at 0x1000 */
	memset(M.mmio_idx, 0, sizeof M.mmio_idx);
	mmio_reads = mmio_writes = mmio_bytes = 0;
	mmio_addr = mmio_val = mmio_ret = 0;
	excl_bytes = 0;
	excl_value = 0;
}

static void reset_pc0(void)
{
	reset();
	C.r[15] = 8;                   /* instruction at address 0 */
	C.next_pc = 4;
}

/* ------------------------------------------------------------------ LDR / STR word */

static void t_ldr_imm(void)
{
	reset();
	raw_st32(0x1000, 0xA1B2C3D4u);
	C.r[1] = 0x1000;
	MEM_OK(E_LDR_IMM0);
	CHECK_EQ(C.r[0], 0xA1B2C3D4u);
	CHECK_EQ(C.r[1], 0x1000);
	CHECK_EQ(C.next_pc, 0x1004);
	CHECK_EQ(C.thumb, 0);
	CHECK_EQ(C.n, 0); CHECK_EQ(C.z, 0); CHECK_EQ(C.cf, 0); CHECK_EQ(C.v, 0);

	reset();
	raw_st32(0x1004, 0x01020304u);
	C.r[1] = 0x1000;
	MEM_OK(E_LDR_IMM4);
	CHECK_EQ(C.r[0], 0x01020304u);

	reset();
	raw_st32(0x0FFC, 0xDEADBEEFu);
	C.r[1] = 0x1000;
	MEM_OK(E_LDR_IMM_NEG4);
	CHECK_EQ(C.r[0], 0xDEADBEEFu);
	CHECK_EQ(C.r[1], 0x1000);

	reset();
	raw_st32(0x1ABC, 0x55667788u);
	C.r[1] = 0x1000;
	MEM_OK(E_LDR_IMM_ABC);
	CHECK_EQ(C.r[2], 0x55667788u);
	CHECK_EQ(C.r[1], 0x1000);

	/* zero offset and a zero result exercise Z/N in the data path (flags must stay clear) */
	reset();
	raw_st32(0x1000, 0x00000000u);
	C.r[1] = 0x1000;
	MEM_OK(E_LDR_IMM0);
	CHECK_EQ(C.r[0], 0);
	CHECK_EQ(C.n | (C.z << 1), 0);
}

static void t_ldr_post(void)
{
	reset();
	raw_st32(0x1000, 0x11111111u);
	C.r[1] = 0x1000;
	MEM_OK(E_LDR_POST4);
	CHECK_EQ(C.r[0], 0x11111111u);
	CHECK_EQ(C.r[1], 0x1004);

	reset();
	raw_st32(0x1000, 0x22222222u);
	C.r[1] = 0x1000;
	MEM_OK(E_LDR_POST_NEG4);
	CHECK_EQ(C.r[0], 0x22222222u);
	CHECK_EQ(C.r[1], 0x0FFC);

	reset();
	raw_st32(0x1000, 0x33333333u);
	C.r[1] = 0x1000;
	C.r[2] = 8;
	MEM_OK(E_LDR_POST_REG);
	CHECK_EQ(C.r[0], 0x33333333u);
	CHECK_EQ(C.r[1], 0x1008);

	reset();
	raw_st32(0x1000, 0x44444444u);
	C.r[1] = 0x1000;
	C.r[2] = 4;
	MEM_OK(E_LDR_POST_REG_NEG_LSL1);
	CHECK_EQ(C.r[0], 0x44444444u);
	CHECK_EQ(C.r[1], 0x0FF8);
}

static void t_ldr_pre_wb(void)
{
	reset();
	raw_st32(0x0FFC, 0x0F0E0D0Cu);
	C.r[1] = 0x1000;
	MEM_OK(E_LDR_PRE_NEG4_WB);
	CHECK_EQ(C.r[3], 0x0F0E0D0Cu);
	CHECK_EQ(C.r[1], 0x0FFC);
}

static void t_ldr_reg(void)
{
	reset();
	raw_st32(0x1008, 0x01010101u);
	C.r[1] = 0x1000;
	C.r[2] = 8;
	MEM_OK(E_LDR_REG);
	CHECK_EQ(C.r[0], 0x01010101u);
	CHECK_EQ(C.r[1], 0x1000);

	reset();
	raw_st32(0x100C, 0x02020202u);
	C.r[1] = 0x1000;
	C.r[2] = 3;
	MEM_OK(E_LDR_REG_LSL2);
	CHECK_EQ(C.r[0], 0x02020202u);

	reset();
	raw_st32(0x1004, 0x03030303u);
	C.r[1] = 0x1000;
	C.r[2] = 9;
	MEM_OK(E_LDR_REG_LSR1);
	CHECK_EQ(C.r[0], 0x03030303u);

	reset();
	raw_st32(0x1000, 0x04040404u);
	C.r[1] = 0x1000;
	C.r[2] = 0x80000001u;          /* LSR #32 of anything is 0 */
	MEM_OK(E_LDR_REG_LSR32);
	CHECK_EQ(C.r[0], 0x04040404u);

	reset();
	raw_st32(0x0FFF, 0x05050505u);
	C.r[1] = 0x1000;
	C.r[2] = 0xFFFFFFF0u;
	MEM_OK(E_LDR_REG_ASR4);
	CHECK_EQ(C.r[0], 0x05050505u);

	reset();
	raw_st32(0x0FFF, 0x06060606u);
	C.r[1] = 0x1000;
	C.r[2] = 0x80000000u;
	MEM_OK(E_LDR_REG_ASR32);
	CHECK_EQ(C.r[0], 0x06060606u);

	reset();
	raw_st32(0x1001, 0x07070707u);
	C.r[1] = 0x1000;
	C.r[2] = 0x00000100u;
	MEM_OK(E_LDR_REG_ROR8);
	CHECK_EQ(C.r[0], 0x07070707u);

	reset();
	raw_st32(0x1001, 0x08080808u);
	C.r[1] = 0x1000;
	C.r[2] = 2;
	MEM_OK(E_LDR_REG_RRX);
	CHECK_EQ(C.r[0], 0x08080808u);

	/* RRX with C=1: (2 >> 1) | 0x80000000 = 0x80000001; 0x80000000 + that wraps to 1 */
	reset();
	raw_st32(0x0001, 0x09090909u);
	C.r[1] = 0x80000000u;
	C.r[2] = 2;
	C.cf = 1;
	MEM_OK(E_LDR_REG_RRX);
	CHECK_EQ(C.r[0], 0x09090909u);
	CHECK_EQ(C.cf, 1);

	reset();
	raw_st32(0x0FF8, 0x0A0A0A0Au);
	C.r[1] = 0x1000;
	C.r[2] = 8;
	MEM_OK(E_LDR_REG_NEG);
	CHECK_EQ(C.r[0], 0x0A0A0A0Au);

	reset();
	raw_st32(0x0FF8, 0x0B0B0B0Bu);
	C.r[1] = 0x1000;
	C.r[2] = 1;
	MEM_OK(E_LDR_REG_NEG_LSL3);
	CHECK_EQ(C.r[0], 0x0B0B0B0Bu);
}

static void t_ldr_literal(void)
{
	reset();
	raw_st32(0x1018, 0xFEEDFACEu);
	MEM_OK(E_LDR_LITERAL);
	CHECK_EQ(C.r[0], 0xFEEDFACEu);
	CHECK_EQ(C.r[15], 0x1008);

	reset();
	raw_st32(0x1004, 0xC0FFEE00u);
	MEM_OK(E_LDR_LITERAL_NEG);
	CHECK_EQ(C.r[0], 0xC0FFEE00u);
}

static void t_ldr_pc(void)
{
	reset();
	raw_st32(0x1000, 0x00002001u);
	C.r[1] = 0x1000;
	MEM_OK(E_LDR_PC);
	CHECK_EQ(C.next_pc, 0x2000);
	CHECK_EQ(C.thumb, 1);
	CHECK_EQ(C.r[1], 0x1000);

	reset();
	raw_st32(0x1000, 0x00002000u);
	C.r[1] = 0x1000;
	MEM_OK(E_LDR_PC);
	CHECK_EQ(C.next_pc, 0x2000);
	CHECK_EQ(C.thumb, 0);

	reset();
	raw_st32(0x1004, 0x00002001u);
	C.r[1] = 0x1000;
	MEM_OK(E_LDR_PC_WB);
	CHECK_EQ(C.next_pc, 0x2000);
	CHECK_EQ(C.thumb, 1);
	CHECK_EQ(C.r[1], 0x1004);
}

static void t_ldrb(void)
{
	reset();
	raw_st32(0x1000, 0xAABBCCDDu);
	C.r[1] = 0x1000;
	MEM_OK(E_LDRB_IMM3);
	CHECK_EQ(C.r[0], 0x000000AAu);
	CHECK_EQ(C.r[1], 0x1000);

	reset();
	raw_st32(0x0FFC, 0x11223344u);
	C.r[1] = 0x1000;
	MEM_OK(E_LDRB_NEG1);
	CHECK_EQ(C.r[0], 0x00000011u);

	reset();
	raw_st8(0x1000, 0x5A);
	C.r[1] = 0x1000;
	MEM_OK(E_LDRB_POST1);
	CHECK_EQ(C.r[0], 0x0000005Au);
	CHECK_EQ(C.r[1], 0x1001);

	reset();
	raw_st8(0x1004, 0x77);
	C.r[1] = 0x1000;
	C.r[2] = 2;
	MEM_OK(E_LDRB_REG_LSL1);
	CHECK_EQ(C.r[0], 0x00000077u);

	reset();
	raw_st8(0x0FFE, 0x5A);
	C.r[1] = 0x1000;
	C.r[2] = 2;
	MEM_OK(E_LDRB_REG_NEG);
	CHECK_EQ(C.r[0], 0x0000005Au);

	reset();
	raw_st32(0x1000, 0xFFFFFFFFu);
	C.r[0] = 0xA5;
	C.r[1] = 0x1000;
	C.r[2] = 3;
	MEM_OK(E_STRB_REG);
	CHECK_EQ(raw_ld8(0x100C), 0xA5u);
	CHECK_EQ(raw_ld32(0x1000), 0xFFFFFFFFu);
}

static void t_str(void)
{
	reset();
	C.r[0] = 0x12345678u;
	C.r[1] = 0x1000;
	MEM_OK(E_STR_IMM0);
	CHECK_EQ(raw_ld32(0x1000), 0x12345678u);
	CHECK_EQ(C.r[1], 0x1000);

	reset();
	C.r[0] = 0x87654321u;
	C.r[1] = 0x1000;
	MEM_OK(E_STR_IMM4);
	CHECK_EQ(raw_ld32(0x1004), 0x87654321u);

	reset();
	C.r[0] = 0xCAFEBABEu;
	C.r[1] = 0x1000;
	MEM_OK(E_STR_PRE_NEG4_WB);
	CHECK_EQ(raw_ld32(0x0FFC), 0xCAFEBABEu);
	CHECK_EQ(C.r[1], 0x0FFC);

	reset();
	C.r[0] = 0x0BADCAFEu;
	C.r[1] = 0x1000;
	MEM_OK(E_STR_POST4);
	CHECK_EQ(raw_ld32(0x1000), 0x0BADCAFEu);
	CHECK_EQ(C.r[1], 0x1004);

	reset();
	C.r[1] = 0x1000;
	C.r[2] = 0xABCDEF01u;
	C.r[3] = 0x00010000u;         /* ROR #16 -> 1 */
	MEM_OK(E_STR_REG_ROR16);
	CHECK_EQ(raw_ld32(0x1001), 0xABCDEF01u);

	reset();
	C.r[1] = 0x1000;
	MEM_OK(E_STR_PC);
	CHECK_EQ(raw_ld32(0x1000), 0x1008u);   /* STR pc stores address + 8 */

	reset();
	raw_st32(0x1000, 0xFFFFFFFFu);
	C.r[0] = 0xAA;
	C.r[1] = 0x1000;
	MEM_OK(E_STRB_IMM3);
	CHECK_EQ(raw_ld32(0x1000), 0xAAFFFFFFu);

	reset();
	C.r[0] = 0x7F;
	C.r[1] = 0x1000;
	MEM_OK(E_STRB_POST_NEG3);
	CHECK_EQ(raw_ld8(0x1000), 0x7Fu);
	CHECK_EQ(C.r[1], 0x0FFD);

	reset();
	C.r[0] = 0x11223344u;
	C.r[1] = 0x1000;
	C.r[2] = 2;
	MEM_OK(E_STR_REG_NEG);
	CHECK_EQ(raw_ld32(0x0FFC), 0x11223344u);

	reset();
	C.r[0] = 0x55667788u;
	C.r[1] = 0x1000;
	C.r[2] = 8;
	MEM_OK(E_STR_POST_REG);
	CHECK_EQ(raw_ld32(0x1000), 0x55667788u);
	CHECK_EQ(C.r[1], 0x1008);
}

static void t_ldrt_strt(void)
{
	reset();
	raw_st32(0x1004, 0x0BADF00Du);
	C.r[1] = 0x1000;
	MEM_OK(E_LDRT4);
	CHECK_EQ(C.r[0], 0x0BADF00Du);
	CHECK_EQ(C.r[1], 0x1000);     /* unprivileged form: no writeback */

	reset();
	C.r[0] = 0xFEEDFACEu;
	C.r[1] = 0x1000;
	MEM_OK(E_STRT_NEG4);
	CHECK_EQ(raw_ld32(0x0FFC), 0xFEEDFACEu);
	CHECK_EQ(C.r[1], 0x1000);

	reset();
	raw_st8(0x1000, 0x99);
	C.r[1] = 0x1000;
	MEM_OK(E_LDRBT);
	CHECK_EQ(C.r[0], 0x99u);
	CHECK_EQ(C.r[1], 0x1000);

	reset();
	C.r[0] = 0x55;
	C.r[1] = 0x1000;
	MEM_OK(E_STRBT1);
	CHECK_EQ(raw_ld8(0x1001), 0x55u);
	CHECK_EQ(C.r[1], 0x1000);
}

static void t_mmio(void)
{
	reset();
	M.mmio_idx[3] = 1;
	M.mmio[1].rd = test_mmio_rd;
	M.mmio[1].wr = test_mmio_wr;
	M.mmio[1].ctx = NULL;
	mmio_ret = 0x13572468u;
	C.r[1] = 0x300004;
	MEM_OK(E_LDR_IMM0);
	CHECK_EQ(C.r[0], 0x13572468u);
	CHECK_EQ(mmio_reads, 1);
	CHECK_EQ(mmio_addr, 0x300004);
	CHECK_EQ(mmio_bytes, 4);

	C.r[0] = 0x24681357u;
	C.r[1] = 0x300004;
	MEM_OK(E_STR_IMM4);
	CHECK_EQ(mmio_writes, 1);
	CHECK_EQ(mmio_addr, 0x300008);
	CHECK_EQ(mmio_bytes, 4);
	CHECK_EQ(mmio_val, 0x24681357u);

	mmio_ret = 0x89ABCDEFu;
	C.r[1] = 0x300000;
	MEM_OK(E_LDRB_IMM3);
	CHECK_EQ(mmio_reads, 2);
	CHECK_EQ(mmio_addr, 0x300003);
	CHECK_EQ(mmio_bytes, 1);
	CHECK_EQ(C.r[0], 0xEFu);
}

/* ------------------------------------------------------------------ halfword / signed */

static void t_ldrh(void)
{
	reset();
	raw_st32(0x1004, 0xBEEF1234u);
	C.r[1] = 0x1000;
	MEM_OK(E_LDRH_IMM6);
	CHECK_EQ(C.r[0], 0xBEEFu);
	CHECK_EQ(C.r[1], 0x1000);

	reset();
	raw_st32(0x0FF8, 0x11223344u);
	C.r[1] = 0x1000;
	MEM_OK(E_LDRH_NEG6);
	CHECK_EQ(C.r[0], 0x1122u);

	reset();
	raw_st16(0x1000, 0xCAFE);
	C.r[1] = 0x1000;
	MEM_OK(E_LDRH_POST6);
	CHECK_EQ(C.r[0], 0xCAFEu);
	CHECK_EQ(C.r[1], 0x1006);

	reset();
	raw_st16(0x1006, 0xF00D);
	C.r[1] = 0x1000;
	MEM_OK(E_LDRH_PRE_WB);
	CHECK_EQ(C.r[0], 0xF00Du);
	CHECK_EQ(C.r[1], 0x1006);

	reset();
	raw_st16(0x1006, 0x1234);
	C.r[1] = 0x1000;
	C.r[2] = 6;
	MEM_OK(E_LDRH_REG);
	CHECK_EQ(C.r[0], 0x1234u);

	reset();
	raw_st16(0x0FFE, 0xCAFE);
	C.r[1] = 0x1000;
	C.r[2] = 2;
	MEM_OK(E_LDRH_REG_NEG);
	CHECK_EQ(C.r[0], 0xCAFEu);

	reset();
	C.r[1] = 0x1000;
	MEM_UNDEF(E_LDRH_PC);          /* Rt=15: UNPREDICTABLE */
}

static void t_strh(void)
{
	reset();
	raw_st32(0x1000, 0xFFFFFFFFu);
	C.r[0] = 0x1234;
	C.r[1] = 0x1000;
	MEM_OK(E_STRH_IMM2);
	CHECK_EQ(raw_ld32(0x1000), 0x1234FFFFu);

	reset();
	C.r[0] = 0xABCD;
	C.r[1] = 0x1000;
	MEM_OK(E_STRH_POST_NEG2);
	CHECK_EQ(raw_ld16(0x1000), 0xABCDu);
	CHECK_EQ(C.r[1], 0x0FFE);

	reset();
	C.r[0] = 0xBEEF;
	C.r[1] = 0x1000;
	C.r[2] = 4;
	MEM_OK(E_STRH_REG);
	CHECK_EQ(raw_ld16(0x1004), 0xBEEFu);

	reset();
	C.r[0] = 0xF00D;
	C.r[1] = 0x1000;
	C.r[2] = 2;
	MEM_OK(E_STRH_REG_NEG);
	CHECK_EQ(raw_ld16(0x0FFE), 0xF00Du);
}

static void t_ldrsb(void)
{
	reset();
	raw_st32(0x1000, 0x00008000u);
	C.r[1] = 0x1000;
	MEM_OK(E_LDRSB_1);
	CHECK_EQ(C.r[0], 0xFFFFFF80u);

	reset();
	raw_st8(0x1000, 0x80);
	C.r[1] = 0x1000;
	MEM_OK(E_LDRSB_POST_NEG1);
	CHECK_EQ(C.r[0], 0xFFFFFF80u);
	CHECK_EQ(C.r[1], 0x0FFF);

	reset();
	raw_st8(0x1001, 0x80);
	C.r[1] = 0x1000;
	C.r[2] = 1;
	MEM_OK(E_LDRSB_REG);
	CHECK_EQ(C.r[0], 0xFFFFFF80u);

	reset();
	raw_st8(0x1000, 0x7F);
	C.r[1] = 0x1000;
	MEM_OK(E_LDRSB_POST_NEG1);
	CHECK_EQ(C.r[0], 0x0000007Fu);

	reset();
	raw_st8(0x0FFE, 0x80);
	C.r[1] = 0x1000;
	C.r[2] = 2;
	MEM_OK(E_LDRSB_REG_NEG);
	CHECK_EQ(C.r[0], 0xFFFFFF80u);
}

static void t_ldrsh(void)
{
	reset();
	raw_st32(0x1000, 0x80010000u);
	C.r[1] = 0x1000;
	MEM_OK(E_LDRSH_2);
	CHECK_EQ(C.r[0], 0xFFFF8001u);

	reset();
	raw_st16(0x1000, 0x8001);
	C.r[1] = 0x1000;
	MEM_OK(E_LDRSH_POST2);
	CHECK_EQ(C.r[0], 0xFFFF8001u);
	CHECK_EQ(C.r[1], 0x1002);

	reset();
	raw_st16(0x1002, 0x8001);
	C.r[1] = 0x1000;
	C.r[2] = 2;
	MEM_OK(E_LDRSH_REG);
	CHECK_EQ(C.r[0], 0xFFFF8001u);

	reset();
	raw_st16(0x1000, 0x7FFF);
	C.r[1] = 0x1000;
	MEM_OK(E_LDRSH_POST2);
	CHECK_EQ(C.r[0], 0x00007FFFu);

	reset();
	raw_st16(0x0FFE, 0x8001);
	C.r[1] = 0x1000;
	C.r[2] = 2;
	MEM_OK(E_LDRSH_REG_NEG);
	CHECK_EQ(C.r[0], 0xFFFF8001u);

	reset();
	C.r[1] = 0x1000;
	MEM_UNDEF(E_LDRSH_PC);
}

/* ------------------------------------------------------------------ doubleword */

static void t_ldrd(void)
{
	reset();
	raw_st32(0x1008, 0x11111111u);
	raw_st32(0x100C, 0x22222222u);
	C.r[5] = 0x1000;
	MEM_OK(E_LDRD_IMM8);
	CHECK_EQ(C.r[0], 0x11111111u);
	CHECK_EQ(C.r[1], 0x22222222u);
	CHECK_EQ(C.r[5], 0x1000);

	reset();
	raw_st32(0x0FF8, 0x33333333u);
	raw_st32(0x0FFC, 0x44444444u);
	C.r[5] = 0x1000;
	MEM_OK(E_LDRD_NEG8);
	CHECK_EQ(C.r[2], 0x33333333u);
	CHECK_EQ(C.r[3], 0x44444444u);

	reset();
	raw_st32(0x1000, 0x55555555u);
	raw_st32(0x1004, 0x66666666u);
	C.r[5] = 0x1000;
	MEM_OK(E_LDRD_POST8);
	CHECK_EQ(C.r[0], 0x55555555u);
	CHECK_EQ(C.r[1], 0x66666666u);
	CHECK_EQ(C.r[5], 0x1008);

	reset();
	raw_st32(0x1008, 0x77777777u);
	raw_st32(0x100C, 0x88888888u);
	C.r[5] = 0x1000;
	MEM_OK(E_LDRD_PRE_WB);
	CHECK_EQ(C.r[0], 0x77777777u);
	CHECK_EQ(C.r[1], 0x88888888u);
	CHECK_EQ(C.r[5], 0x1008);

	reset();
	raw_st32(0x1008, 0x99999999u);
	raw_st32(0x100C, 0xAAAAAAAAu);
	C.r[5] = 0x1000;
	C.r[6] = 8;
	MEM_OK(E_LDRD_REG);
	CHECK_EQ(C.r[0], 0x99999999u);
	CHECK_EQ(C.r[1], 0xAAAAAAAAu);

	reset();
	raw_st32(0x0FF8, 0xBBBBBBBBu);
	raw_st32(0x0FFC, 0xCCCCCCCCu);
	C.r[5] = 0x1000;
	C.r[6] = 8;
	MEM_OK(E_LDRD_REG_NEG);
	CHECK_EQ(C.r[0], 0xBBBBBBBBu);
	CHECK_EQ(C.r[1], 0xCCCCCCCCu);
}

static void t_strd(void)
{
	reset();
	C.r[5] = 0x1000;
	C.r[0] = 0xDEAD0001u;
	C.r[1] = 0xDEAD0002u;
	MEM_OK(E_STRD_IMM8);
	CHECK_EQ(raw_ld32(0x1008), 0xDEAD0001u);
	CHECK_EQ(raw_ld32(0x100C), 0xDEAD0002u);

	reset();
	C.r[5] = 0x1000;
	C.r[2] = 0xBEEF0003u;
	C.r[3] = 0xBEEF0004u;
	MEM_OK(E_STRD_POST_NEG8);
	CHECK_EQ(raw_ld32(0x1000), 0xBEEF0003u);
	CHECK_EQ(raw_ld32(0x1004), 0xBEEF0004u);
	CHECK_EQ(C.r[5], 0x0FF8);

	reset();
	C.r[5] = 0x1000;
	C.r[6] = 8;
	C.r[2] = 0xFEED0005u;
	C.r[3] = 0xFEED0006u;
	MEM_OK(E_STRD_REG);
	CHECK_EQ(raw_ld32(0x1008), 0xFEED0005u);
	CHECK_EQ(raw_ld32(0x100C), 0xFEED0006u);

	reset();
	C.r[5] = 0x1000;
	C.r[0] = 0xCAFE0007u;
	C.r[1] = 0xCAFE0008u;
	MEM_OK(E_STRD_PRE_NEG8_WB);
	CHECK_EQ(raw_ld32(0x0FF8), 0xCAFE0007u);
	CHECK_EQ(raw_ld32(0x0FFC), 0xCAFE0008u);
	CHECK_EQ(C.r[5], 0x0FF8);

	reset();
	C.r[5] = 0x1000;
	C.r[6] = 8;
	C.r[2] = 0xD00D0009u;
	C.r[3] = 0xD00D000Au;
	MEM_OK(E_STRD_REG_NEG);
	CHECK_EQ(raw_ld32(0x0FF8), 0xD00D0009u);
	CHECK_EQ(raw_ld32(0x0FFC), 0xD00D000Au);
}

/* ------------------------------------------------------------------ LDM / STM */

static void t_ldm_modes(void)
{
	reset();
	raw_st32(0x1000, 0x10000001u);
	raw_st32(0x1004, 0x10000002u);
	C.r[0] = 0x1000;
	MEM_OK(E_LDMIA);
	CHECK_EQ(C.r[1], 0x10000001u);
	CHECK_EQ(C.r[2], 0x10000002u);
	CHECK_EQ(C.r[0], 0x1000);

	reset();
	raw_st32(0x1000, 0x20000001u);
	raw_st32(0x1004, 0x20000002u);
	C.r[0] = 0x1000;
	MEM_OK(E_LDMIA_WB);
	CHECK_EQ(C.r[1], 0x20000001u);
	CHECK_EQ(C.r[2], 0x20000002u);
	CHECK_EQ(C.r[0], 0x1008);

	reset();
	raw_st32(0x1004, 0x30000001u);
	raw_st32(0x1008, 0x30000002u);
	raw_st32(0x100C, 0x30000003u);
	C.r[0] = 0x1000;
	MEM_OK(E_LDMIB);
	CHECK_EQ(C.r[1], 0x30000001u);
	CHECK_EQ(C.r[2], 0x30000002u);
	CHECK_EQ(C.r[3], 0x30000003u);
	CHECK_EQ(C.r[0], 0x1000);

	/* DA: start = base - 4*n + 4 = 0x0FF8; writeback base - 4*n = 0x0FF4 */
	reset();
	raw_st32(0x0FF8, 0x40000001u);
	raw_st32(0x0FFC, 0x40000002u);
	raw_st32(0x1000, 0x40000003u);
	C.r[0] = 0x1000;
	MEM_OK(E_LDMDA_WB);
	CHECK_EQ(C.r[1], 0x40000001u);
	CHECK_EQ(C.r[2], 0x40000002u);
	CHECK_EQ(C.r[3], 0x40000003u);
	CHECK_EQ(C.r[0], 0x0FF4);

	/* DB: start = base - 4*n = 0x0FF4 */
	reset();
	raw_st32(0x0FF4, 0x50000001u);
	raw_st32(0x0FF8, 0x50000002u);
	raw_st32(0x0FFC, 0x50000003u);
	C.r[0] = 0x1000;
	MEM_OK(E_LDMDB_WB);
	CHECK_EQ(C.r[1], 0x50000001u);
	CHECK_EQ(C.r[2], 0x50000002u);
	CHECK_EQ(C.r[3], 0x50000003u);
	CHECK_EQ(C.r[0], 0x0FF4);
}

static void t_ldm_pc(void)
{
	reset();
	raw_st32(0x1000, 0x60000001u);
	raw_st32(0x1004, 0x60000002u);
	raw_st32(0x1008, 0x60000003u);
	raw_st32(0x100C, 0x00002001u);
	C.r[0] = 0x1000;
	MEM_OK(E_LDM_PC);
	CHECK_EQ(C.r[1], 0x60000001u);
	CHECK_EQ(C.r[2], 0x60000002u);
	CHECK_EQ(C.r[3], 0x60000003u);
	CHECK_EQ(C.next_pc, 0x2000);
	CHECK_EQ(C.thumb, 1);
	CHECK_EQ(C.r[0], 0x1000);

	reset();
	raw_st32(0x1000, 0x61000001u);
	raw_st32(0x1004, 0x61000002u);
	raw_st32(0x1008, 0x61000003u);
	raw_st32(0x100C, 0x00002000u);
	C.r[0] = 0x1000;
	MEM_OK(E_LDM_PC_WB);
	CHECK_EQ(C.r[1], 0x61000001u);
	CHECK_EQ(C.next_pc, 0x2000);
	CHECK_EQ(C.thumb, 0);
	CHECK_EQ(C.r[0], 0x1010);
}

static void t_push_pop(void)
{
	reset();
	raw_st32(0x00F00000u, 0x0000AAAAu);
	raw_st32(0x00F00004u, 0x00002000u);
	MEM_OK(E_POP_PC);
	CHECK_EQ(C.r[0], 0x0000AAAAu);
	CHECK_EQ(C.next_pc, 0x2000);
	CHECK_EQ(C.thumb, 0);
	CHECK_EQ(C.r[13], 0x00F00008u);

	reset();
	C.r[0] = 0x11;
	C.r[1] = 0x22;
	C.r[2] = 0x33;
	C.r[14] = 0x44;
	MEM_OK(E_PUSH_LR);
	CHECK_EQ(C.r[13], 0x00EFFFF0u);
	CHECK_EQ(raw_ld32(0x00EFFFF0u), 0x11u);
	CHECK_EQ(raw_ld32(0x00EFFFF4u), 0x22u);
	CHECK_EQ(raw_ld32(0x00EFFFF8u), 0x33u);
	CHECK_EQ(raw_ld32(0x00EFFFFCu), 0x44u);
}

static void t_stm_modes(void)
{
	reset();
	C.r[0] = 0x1000;
	C.r[1] = 0x70000001u;
	C.r[2] = 0x70000002u;
	MEM_OK(E_STMIA_WB);
	CHECK_EQ(raw_ld32(0x1000), 0x70000001u);
	CHECK_EQ(raw_ld32(0x1004), 0x70000002u);
	CHECK_EQ(C.r[0], 0x1008);

	reset();
	C.r[0] = 0x1000;
	C.r[1] = 0x71000001u;
	C.r[2] = 0x71000002u;
	MEM_OK(E_STMIB);
	CHECK_EQ(raw_ld32(0x1004), 0x71000001u);
	CHECK_EQ(raw_ld32(0x1008), 0x71000002u);
	CHECK_EQ(C.r[0], 0x1000);

	/* DA: start = 0x1000 - 8 + 4 = 0x0FFC */
	reset();
	C.r[0] = 0x1000;
	C.r[1] = 0x72000001u;
	C.r[2] = 0x72000002u;
	MEM_OK(E_STMDA_WB);
	CHECK_EQ(raw_ld32(0x0FFC), 0x72000001u);
	CHECK_EQ(raw_ld32(0x1000), 0x72000002u);
	CHECK_EQ(C.r[0], 0x0FF8);

	/* DB: start = 0x0FF8 */
	reset();
	C.r[0] = 0x1000;
	C.r[1] = 0x73000001u;
	C.r[2] = 0x73000002u;
	MEM_OK(E_STMDB_WB);
	CHECK_EQ(raw_ld32(0x0FF8), 0x73000001u);
	CHECK_EQ(raw_ld32(0x0FFC), 0x73000002u);
	CHECK_EQ(C.r[0], 0x0FF8);
}

static void t_stm_base_in_list(void)
{
	reset();
	C.r[0] = 0x1000;
	C.r[1] = 0x80000001u;
	C.r[2] = 0x80000002u;
	C.r[3] = 0x80000003u;
	MEM_OK(E_STMIB_BASE_IN_LIST);      /* W=0: no writeback, stores the old base */
	CHECK_EQ(raw_ld32(0x1004), 0x1000u);
	CHECK_EQ(raw_ld32(0x1008), 0x80000001u);
	CHECK_EQ(raw_ld32(0x100C), 0x80000002u);
	CHECK_EQ(raw_ld32(0x1010), 0x80000003u);
	CHECK_EQ(C.r[0], 0x1000);

	reset();
	C.r[0] = 0x1000;
	C.r[1] = 0x81000001u;
	C.r[2] = 0x81000002u;
	C.r[3] = 0x81000003u;
	MEM_OK(E_STMDB_BASE_IN_LIST_WB);   /* stores old base at 0x0FF0, then writes back */
	CHECK_EQ(raw_ld32(0x0FF0), 0x1000u);
	CHECK_EQ(raw_ld32(0x0FF4), 0x81000001u);
	CHECK_EQ(raw_ld32(0x0FF8), 0x81000002u);
	CHECK_EQ(raw_ld32(0x0FFC), 0x81000003u);
	CHECK_EQ(C.r[0], 0x0FF0);
}

static void t_stm_pc_and_s_bit(void)
{
	reset();
	C.r[0] = 0x1000;
	MEM_OK(E_STM_PC);
	CHECK_EQ(raw_ld32(0x1000), 0x1008u);

	reset();
	C.r[0] = 0x1000;
	MEM_UNDEF(E_LDM_S);
	CHECK_EQ(C.r[0], 0x1000);
	MEM_UNDEF(E_STM_S);
	CHECK_EQ(raw_ld32(0x1000), 0u);
}

/* ------------------------------------------------------------------ exclusives */

static void t_excl_word(void)
{
	reset();
	raw_st32(0x1000, 0xCAFEBABEu);
	C.r[1] = 0x1000;
	MEM_OK(E_LDREX);
	CHECK_EQ(C.r[0], 0xCAFEBABEu);
	CHECK_EQ(C.excl_valid, 1);
	CHECK_EQ(C.excl_addr, 0x1000u);
	CHECK_EQ(excl_bytes, 4);
	CHECK64(excl_value, 0xCAFEBABEu);

	C.r[0] = 0x12345678u;
	MEM_OK(E_STREX);
	CHECK_EQ(C.r[2], 0);
	CHECK_EQ(raw_ld32(0x1000), 0x12345678u);
	CHECK_EQ(C.excl_valid, 0);

	/* no monitor: store fails and memory is untouched */
	reset();
	raw_st32(0x1000, 0x11111111u);
	C.r[0] = 0x22222222u;
	C.r[1] = 0x1000;
	MEM_OK(E_STREX);
	CHECK_EQ(C.r[2], 1);
	CHECK_EQ(raw_ld32(0x1000), 0x11111111u);

	/* memory changed after the load: the value-based CAS fails */
	reset();
	raw_st32(0x1000, 0xAAAAAAAAu);
	C.r[1] = 0x1000;
	MEM_OK(E_LDREX);
	raw_st32(0x1000, 0xBBBBBBBBu);
	C.r[0] = 0xCCCCCCCCu;
	MEM_OK(E_STREX);
	CHECK_EQ(C.r[2], 1);
	CHECK_EQ(raw_ld32(0x1000), 0xBBBBBBBBu);
}

static void t_excl_byte_half(void)
{
	reset();
	raw_st32(0x1000, 0xAABBCCDDu);
	C.r[1] = 0x1000;
	MEM_OK(E_LDREXB);
	CHECK_EQ(C.r[0], 0xDDu);
	CHECK_EQ(excl_bytes, 1);
	CHECK_EQ(C.excl_addr, 0x1000u);
	C.r[0] = 0x77;
	MEM_OK(E_STREXB);
	CHECK_EQ(C.r[2], 0);
	CHECK_EQ(raw_ld32(0x1000), 0xAABBCC77u);

	reset();
	raw_st32(0x1000, 0xAABBCCDDu);
	C.r[1] = 0x1002;
	MEM_OK(E_LDREXH);
	CHECK_EQ(C.r[0], 0xAABBu);
	CHECK_EQ(excl_bytes, 2);
	C.r[0] = 0x1234;
	MEM_OK(E_STREXH);
	CHECK_EQ(C.r[2], 0);
	CHECK_EQ(raw_ld32(0x1000), 0x1234CCDDu);

	/* failed halfword store: no monitor */
	reset();
	raw_st32(0x1000, 0xAABBCCDDu);
	C.r[0] = 0x1234;
	C.r[1] = 0x1002;
	MEM_OK(E_STREXH);
	CHECK_EQ(C.r[2], 1);
	CHECK_EQ(raw_ld32(0x1000), 0xAABBCCDDu);
}

static void t_excl_double(void)
{
	reset();
	raw_st32(0x1000, 0x01234567u);
	raw_st32(0x1004, 0x89ABCDEFu);
	C.r[4] = 0x1000;
	MEM_OK(E_LDREXD);
	CHECK_EQ(C.r[0], 0x01234567u);
	CHECK_EQ(C.r[1], 0x89ABCDEFu);
	CHECK_EQ(C.r[4], 0x1000u);
	CHECK_EQ(excl_bytes, 8);
	CHECK64(excl_value, 0x89ABCDEF01234567ull);

	C.r[0] = 0x11111111u;
	C.r[1] = 0x22222222u;
	C.r[2] = 0;                        /* Rd = r2 for STREXD */
	MEM_OK(E_STREXD);
	CHECK_EQ(C.r[2], 0);
	CHECK_EQ(raw_ld32(0x1000), 0x11111111u);
	CHECK_EQ(raw_ld32(0x1004), 0x22222222u);

	/* failed doubleword store: memory changed */
	reset();
	raw_st32(0x1000, 0x01234567u);
	raw_st32(0x1004, 0x89ABCDEFu);
	C.r[4] = 0x1000;
	MEM_OK(E_LDREXD);
	raw_st32(0x1000, 0x55555555u);
	C.r[0] = 0x11111111u;
	C.r[1] = 0x22222222u;
	C.r[2] = 0;
	MEM_OK(E_STREXD);
	CHECK_EQ(C.r[2], 1);
	CHECK_EQ(raw_ld32(0x1000), 0x55555555u);
}

static void t_clrex(void)
{
	reset();
	raw_st32(0x1000, 0x01020304u);
	C.r[1] = 0x1000;
	MEM_OK(E_LDREX);
	CHECK_EQ(C.excl_valid, 1);
	MEM_OK(E_CLREX);
	CHECK_EQ(C.excl_valid, 0);
	C.r[0] = 0xDEADDEADu;
	MEM_OK(E_STREX);
	CHECK_EQ(C.r[2], 1);
	CHECK_EQ(raw_ld32(0x1000), 0x01020304u);
}

/* ------------------------------------------------------------------ preload */

static void t_pld(void)
{
	/* A wild address: a preload must not dereference it. */
	reset();
	C.r[1] = 0xFFFFFFFFu;
	C.r[2] = 0xFFFFFFFFu;
	MEM_OK(E_PLD);
	CHECK_EQ(C.next_pc, 0x1004);
	CHECK_EQ(C.r[1], 0xFFFFFFFFu);

	reset();
	C.r[1] = 0xFFFFFFFFu;
	MEM_OK(E_PLD_IMM4);
	CHECK_EQ(C.r[1], 0xFFFFFFFFu);

	reset();
	C.r[1] = 0xFFFFFFFFu;
	C.r[2] = 0xFFFFFFFFu;
	MEM_OK(E_PLD_NEG_REG);
	CHECK_EQ(C.r[1], 0xFFFFFFFFu);

	reset();
	C.r[1] = 0xFFFFFFFFu;
	C.r[2] = 0xFFFFFFFFu;
	MEM_OK(E_PLD_REG_LSL2);

	reset();
	C.r[1] = 0xFFFFFFFFu;
	C.r[2] = 0xFFFFFFFFu;
	C.cf = 1;
	MEM_OK(E_PLD_REG_RRX);
	CHECK_EQ(C.cf, 1);
}

static void t_pli(void)
{
	reset();
	C.r[1] = 0xFFFFFFFFu;
	MEM_OK(E_PLI);
	reset();
	C.r[1] = 0xFFFFFFFFu;
	MEM_OK(E_PLI_IMM4);
	reset();
	C.r[1] = 0xFFFFFFFFu;
	C.r[2] = 0xFFFFFFFFu;
	MEM_OK(E_PLI_REG);
	reset();
	C.r[1] = 0xFFFFFFFFu;
	C.r[2] = 0xFFFFFFFFu;
	MEM_OK(E_PLI_REG_NEG);
}

static void t_pldw(void)
{
	reset();
	C.r[1] = 0xFFFFFFFFu;
	MEM_OK(E_PLDW);
	reset();
	C.r[1] = 0xFFFFFFFFu;
	MEM_OK(E_PLDW_IMM4);
	reset();
	C.r[1] = 0xFFFFFFFFu;
	C.r[2] = 0xFFFFFFFFu;
	MEM_OK(E_PLDW_NEG_REG);
	reset();
	C.r[1] = 0xFFFFFFFFu;
	C.r[2] = 0xFFFFFFFFu;
	MEM_OK(E_PLDW_REG_LSL2);
}

/* ------------------------------------------------------------------ branches */

static void t_branch_b(void)
{
	reset_pc0();
	MISC_OK(E_B_FWD);
	CHECK_EQ(C.next_pc, 8u + 0x100u);
	CHECK_EQ(C.thumb, 0);
	CHECK_EQ(C.r[14], 0u);          /* B leaves LR alone */

	reset_pc0();
	MISC_OK(E_B_BACK);
	CHECK_EQ(C.next_pc, 0u);        /* 8 + (-8) */

	/* The class function must not re-test the condition: Z=0 here. */
	reset_pc0();
	C.z = 0;
	MISC_OK(E_B_EQ);
	CHECK_EQ(C.next_pc, 8u + 0x80u);
}

static void t_branch_bl(void)
{
	reset_pc0();
	MISC_OK(E_BL_FWD);
	CHECK_EQ(C.r[14], 4u);          /* address of the following instruction */
	CHECK_EQ(C.next_pc, 8u + 0x100u);
	CHECK_EQ(C.thumb, 0);

	reset_pc0();
	MISC_OK(E_BL_BACK);
	CHECK_EQ(C.r[14], 4u);
	CHECK_EQ(C.next_pc, 0u);
}

static void t_branch_blx_imm(void)
{
	reset_pc0();
	MISC_OK(E_BLX_H1);
	CHECK_EQ(C.r[14], 4u);
	CHECK_EQ(C.next_pc, 8u + 0x1122u);
	CHECK_EQ(C.thumb, 1);           /* BLX immediate always selects Thumb */

	reset_pc0();
	MISC_OK(E_BLX_H0);
	CHECK_EQ(C.r[14], 4u);
	CHECK_EQ(C.next_pc, 8u + 0x1120u);
	CHECK_EQ(C.thumb, 1);
}

static void t_branch_bx(void)
{
	reset_pc0();
	C.r[0] = 0x2001;
	MISC_OK(E_BX);
	CHECK_EQ(C.thumb, 1);
	CHECK_EQ(C.next_pc, 0x2000);
	CHECK_EQ(C.r[14], 0u);

	reset_pc0();
	C.r[0] = 0x2000;
	MISC_OK(E_BX);
	CHECK_EQ(C.thumb, 0);
	CHECK_EQ(C.next_pc, 0x2000);

	reset_pc0();
	MISC_OK(E_BX_PC);               /* bx pc with r15 = 8 */
	CHECK_EQ(C.thumb, 0);
	CHECK_EQ(C.next_pc, 8u);
}

static void t_branch_blx_reg(void)
{
	reset_pc0();
	C.r[0] = 0x2001;
	MISC_OK(E_BLX_REG);
	CHECK_EQ(C.r[14], 4u);
	CHECK_EQ(C.thumb, 1);
	CHECK_EQ(C.next_pc, 0x2000);

	reset_pc0();
	C.r[0] = 0x2000;
	MISC_OK(E_BLX_REG);
	CHECK_EQ(C.r[14], 4u);
	CHECK_EQ(C.thumb, 0);
	CHECK_EQ(C.next_pc, 0x2000);
}

/* ------------------------------------------------------------------ system */

static void t_svc(void)
{
	reset();
	MISC_UNDEF(E_SVC0);
	CHECK_EQ(C.stop, N2A32_STOP_SVC);
	CHECK_EQ(C.next_pc, 0x1004);
	CHECK_EQ(C.r[0], 0u);

	reset();
	MISC_UNDEF(E_SVC_BIG);
	CHECK_EQ(C.stop, N2A32_STOP_SVC);
}

static void t_bkpt(void)
{
	reset();
	MISC_UNDEF(E_BKPT0);
	CHECK_EQ(C.stop, N2A32_STOP_BKPT);

	reset();
	MISC_UNDEF(E_BKPT_BIG);
	CHECK_EQ(C.stop, N2A32_STOP_BKPT);
}

static void t_udf(void)
{
	reset();
	MISC_UNDEF(E_UDF0);
	CHECK_EQ(C.stop, N2A32_STOP_UNDEF);

	reset();
	MISC_UNDEF(E_UDF_BIG);
	CHECK_EQ(C.stop, N2A32_STOP_UNDEF);
}

static void t_hints(void)
{
	reset();
	MISC_OK(E_NOP);
	CHECK_EQ(C.next_pc, 0x1004);
	CHECK_EQ(C.r[0], 0u);
	CHECK_EQ(C.stop, N2A32_STOP_NONE);

	reset();
	MISC_OK(E_YIELD);
	CHECK_EQ(C.next_pc, 0x1004);

	reset();
	MISC_OK(E_WFE);
	CHECK_EQ(C.next_pc, 0x1004);

	reset();
	MISC_OK(E_WFI);
	CHECK_EQ(C.next_pc, 0x1004);

	reset();
	MISC_OK(E_SEV);
	CHECK_EQ(C.next_pc, 0x1004);

	reset();
	MISC_OK(E_DBG0);
	CHECK_EQ(C.next_pc, 0x1004);

	reset();
	MISC_OK(E_DBG15);
	CHECK_EQ(C.next_pc, 0x1004);
}

static void t_barriers(void)
{
	reset();
	MISC_OK(E_DMB_SY);
	CHECK_EQ(C.next_pc, 0x1004);
	CHECK_EQ(C.stop, N2A32_STOP_NONE);

	reset();
	MISC_OK(E_DMB_ISH);

	reset();
	MISC_OK(E_DSB_SY);

	reset();
	MISC_OK(E_DSB_ISHST);

	reset();
	MISC_OK(E_ISB_SY);
}

static void t_mrc_tpidruro(void)
{
	reset();
	C.tpidruro = 0xDEADBEEFu;
	MISC_OK(E_MRC_TP0);
	CHECK_EQ(C.r[0], 0xDEADBEEFu);
	CHECK_EQ(C.next_pc, 0x1004);

	reset();
	C.tpidruro = 0x12345678u;
	MISC_OK(E_MRC_TP9);
	CHECK_EQ(C.r[9], 0x12345678u);

	/* condition is the core's business: Z=0 here, the read must still happen */
	reset();
	C.tpidruro = 0x55555555u;
	C.z = 0;
	MISC_OK(E_MRC_TP_COND);
	CHECK_EQ(C.r[5], 0x55555555u);
}

static void t_mrc_undef(void)
{
	reset();
	C.tpidruro = 0xDEADBEEFu;
	MISC_UNDEF(E_MRC_OTHER);
	CHECK_EQ(C.r[0], 0u);

	reset();
	MISC_UNDEF(E_MCR_SAME);
	CHECK_EQ(C.stop, N2A32_STOP_NONE);

	reset();
	MISC_UNDEF(E_MRC_CP14);

	reset();
	MISC_UNDEF(E_MCRR);

	reset();
	MISC_UNDEF(E_MRRC);
}

/* The decode masks must be disjoint between the two entry points. */
static void t_dispatch(void)
{
	reset();
	CHECK_EQ(n2a32_arm_misc(&C, E_LDR_IMM0), N2A32_UNDEF);
	CHECK_EQ(n2a32_arm_mem(&C, E_B_FWD), N2A32_UNDEF);
	CHECK_EQ(n2a32_arm_mem(&C, E_BX), N2A32_UNDEF);
	CHECK_EQ(n2a32_arm_mem(&C, E_NOP), N2A32_UNDEF);
	CHECK_EQ(n2a32_arm_mem(&C, E_MRC_TP0), N2A32_UNDEF);
	CHECK_EQ(n2a32_arm_misc(&C, E_LDMIA), N2A32_UNDEF);
	CHECK_EQ(n2a32_arm_misc(&C, E_LDREX), N2A32_UNDEF);
	CHECK_EQ(n2a32_arm_misc(&C, E_PLD), N2A32_UNDEF);
	CHECK_EQ(n2a32_arm_misc(&C, E_CLREX), N2A32_OK);   /* CLREX is accepted by both */
	CHECK_EQ(n2a32_arm_mem(&C, E_CLREX), N2A32_OK);
	/* The multiply space shares bits 7-4 == 1001 with LDREX/STREX; arm_mem must reject it. */
	CHECK_EQ(n2a32_arm_mem(&C, E_MUL), N2A32_UNDEF);
	CHECK_EQ(n2a32_arm_mem(&C, E_MLA), N2A32_UNDEF);
	CHECK_EQ(n2a32_arm_mem(&C, E_UMULL), N2A32_UNDEF);
	CHECK_EQ(n2a32_arm_mem(&C, E_MLS), N2A32_UNDEF);
	CHECK_EQ(n2a32_arm_mem(&C, E_SWP), N2A32_UNDEF);
}

/* ------------------------------------------------------------------ random sweep */

static uint32_t make_mem_word(uint32_t s)
{
	switch (s % 10u) {
	case 0: return 0xE4000000u | (s & 0x01FFFFFFu);       /* single word/byte, random P/U/B/W/L */
	case 1: return 0xE0000090u | (s & 0x01FF0F6Fu);       /* extra load/store, S/H random */
	case 2: return 0xE8000000u | (s & 0x01FFFFFFu);       /* LDM/STM with random list */
	case 3: return 0xE1900F9Fu | (s & 0x000F0000u);       /* LDREX */
	case 4: return 0xE1B00F9Fu | (s & 0x000F0000u);       /* LDREXD */
	case 5: return 0xE1D00F9Fu | (s & 0x000F0000u);       /* LDREXB */
	case 6: return 0xE1F00F9Fu | (s & 0x000F0000u);       /* LDREXH */
	case 7: return 0xE1800F90u | (s & 0x000FF00Fu);       /* STREX */
	case 8: return 0xF5D0F000u | (s & 0x008F0FFFu);       /* PLD/PLI/PLDW immediate space */
	default: return s;                                    /* arbitrary word */
	}
}

static uint32_t make_misc_word(uint32_t s)
{
	switch (s % 9u) {
	case 0: return 0xEA000000u | (s & 0x00FFFFFFu);       /* B */
	case 1: return 0xEB000000u | (s & 0x00FFFFFFu);       /* BL */
	case 2: return 0xFA000000u | (s & 0x01FFFFFFu);       /* BLX immediate */
	case 3: return 0xE12FFF10u | (s & 0x0000000Fu);       /* BX */
	case 4: return 0xE12FFF30u | (s & 0x0000000Fu);       /* BLX register */
	case 5: return 0xF57FF000u | (s & 0x000000FFu);       /* barriers / CLREX space */
	case 6: return 0xE320F000u | (s & 0x0000000Fu);       /* hints */
	case 7: return 0xEE1D0F70u | (s & 0x0000F000u);       /* MRC p15 */
	default: return s;
	}
}

static void t_sweep(void)
{
	size_t len = ((size_t)4 << 30) + 0x10000u;   /* one guard page past 4 GiB for top accesses */
	void *p = mmap(NULL, len, PROT_READ | PROT_WRITE,
	               MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, 0);
	struct n2a32_mem sm;
	unsigned i;

	if (p == MAP_FAILED) {
		CHECK(!"mmap of the 4 GiB sweep reservation failed");
		return;
	}
	memset(&sm, 0, sizeof sm);
	sm.base = p;

	/* Every encoding llvm-mc produced for this package: OK or UNDEF, never crash. */
	for (i = 0; i < ALL_ENC_N; i++) {
		struct n2a32_cpu c;
		int r;
		memset(&c, 0, sizeof c);
		c.mem = &sm;
		c.r[15] = 8;
		c.next_pc = 4;
		r = n2a32_arm_mem(&c, ALL_ENC[i].word);
		CHECK(r == N2A32_OK || r == N2A32_UNDEF);
		memset(&c, 0, sizeof c);
		c.mem = &sm;
		c.r[15] = 8;
		c.next_pc = 4;
		r = n2a32_arm_misc(&c, ALL_ENC[i].word);
		CHECK(r == N2A32_OK || r == N2A32_UNDEF);
	}

	for (i = 0; i < 200000u; i++) {
		struct n2a32_cpu c;
		uint32_t s = 0x9E3779B9u * (i + 1u) ^ (i << 13);
		uint32_t w;
		int r;

		s ^= s << 13; s ^= s >> 17; s ^= s << 5;
		memset(&c, 0, sizeof c);
		c.mem = &sm;
		c.r[15] = 8;
		c.next_pc = 4;
		if (i & 1u) {
			w = make_mem_word(s);
			r = n2a32_arm_mem(&c, w);
		} else {
			w = make_misc_word(s);
			r = n2a32_arm_misc(&c, w);
		}
		if (r != N2A32_OK && r != N2A32_UNDEF) {
			failures++;
			fprintf(stderr, "FAIL [%s] sweep word 0x%08x returned %d\n", tname, w, r);
		}
		checks++;
	}
	munmap(p, len);
}

