int main(void)
{
	size_t i;

	g_base = calloc(1, GUEST_SIZE);
	if (!g_base) {
		fprintf(stderr, "out of memory\n");
		return 1;
	}
	memset(&M, 0, sizeof M);
	M.base = g_base;

	for (i = 0; i < sizeof TESTS / sizeof TESTS[0]; i++) {
		tname = TESTS[i].name;
		TESTS[i].fn();
	}
	free(g_base);
	if (failures) {
		printf("N2TEST V12 FAIL %u check(s) failed of %u\n", failures, checks);
		return 1;
	}
	printf("N2TEST V12 PASS %u/%u\n", checks, checks);
	return 0;
}
